"mismatch_daily_production" boolean GENERATED ALWAYS AS (((dashboard_daily_production IS NOT NULL) AND (abs((daily_production - dashboard_daily_production)) > 1.00))) STORED,
"mismatch_net_daily_production" boolean GENERATED ALWAYS AS (((dashboard_net_daily_production IS NOT NULL) AND (abs((net_daily_production - dashboard_net_daily_production)) > 1.00))) STORED,
"mismatch_daily_total_coll" boolean GENERATED ALWAYS AS (((dashboard_daily_total_coll IS NOT NULL) AND (abs((daily_total_coll - dashboard_daily_total_coll)) > 1.00))) STORED,
"mismatch_monthly_production" boolean GENERATED ALWAYS AS (((dashboard_monthly_production IS NOT NULL) AND (abs((monthly_production - dashboard_monthly_production)) > 1.00))) STORED,
"mismatch_net_monthly_production" boolean GENERATED ALWAYS AS (((dashboard_net_monthly_production IS NOT NULL) AND (abs((net_monthly_production - dashboard_net_monthly_production)) > 1.00))) STORED,
