CREATE OR REPLACE FUNCTION public.admin_get_user_email(p_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_role TEXT;
  v_email TEXT;
BEGIN
  SELECT role INTO v_caller_role
  FROM public.user_profiles
  WHERE id = auth.uid();

  IF v_caller_role NOT IN ('super_admin', 'admin') THEN
    RAISE EXCEPTION 'Insufficient permissions';
  END IF;

  SELECT email INTO v_email
  FROM public.user_profiles
  WHERE id = p_user_id;

  RETURN v_email;
END;
$function$;

CREATE OR REPLACE FUNCTION public.admin_reset_user_password(p_user_id uuid, p_new_password text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_role TEXT;
  v_caller_id UUID;
BEGIN
  -- Get the calling user's role from user_profiles
  SELECT id INTO v_caller_id FROM auth.users WHERE id = auth.uid();

  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT role INTO v_caller_role
  FROM public.user_profiles
  WHERE id = auth.uid();

  -- Only super_admin or admin can reset passwords
  IF v_caller_role NOT IN ('super_admin', 'admin') THEN
    RAISE EXCEPTION 'Insufficient permissions to reset user passwords';
  END IF;

  -- Validate password length
  IF length(p_new_password) < 10 THEN
    RAISE EXCEPTION 'Password must be at least 10 characters';
  END IF;

  -- Update the user's password in auth.users
  UPDATE auth.users
  SET
    encrypted_password = crypt(p_new_password, gen_salt('bf')),
    updated_at = now()
  WHERE id = p_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'User not found';
  END IF;

  -- Mark user as must change password on next login
  UPDATE public.user_profiles
  SET must_change_password = true
  WHERE id = p_user_id;

  -- Log the admin reset action
  INSERT INTO public.audit_logs (
    user_id,
    action,
    table_name,
    record_id,
    old_values,
    new_values,
    change_summary
  ) VALUES (
    auth.uid(),
    'ADMIN_RESET_PASSWORD',
    'auth.users',
    p_user_id::text,
    NULL,
    jsonb_build_object('password_reset_by_admin', true, 'reset_at', now()),
    'Admin reset password for user ' || p_user_id::text
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.approve_email_draft_with_challenge(p_challenge_id uuid, p_draft_id uuid, p_principal_id text, p_session_id text, p_draft_revision integer, p_content_hash text, p_approved_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  consumed_count INTEGER;
  approved_count INTEGER;
BEGIN
  UPDATE collab_approval_challenges
  SET consumed_at = p_approved_at,
      consumed_by_session_id = p_session_id,
      consumed_result = 'approved'
  WHERE id = p_challenge_id
    AND draft_id = p_draft_id
    AND issued_to_principal = p_principal_id
    AND issued_to_session_id = p_session_id
    AND draft_revision = p_draft_revision
    AND content_hash = p_content_hash
    AND consumed_at IS NULL
    AND invalidated_at IS NULL
    AND expires_at > p_approved_at;
  GET DIAGNOSTICS consumed_count = ROW_COUNT;

  IF consumed_count <> 1 THEN
    RETURN jsonb_build_object('approved', false, 'reason', 'invalid_expired_or_replayed_challenge');
  END IF;

  UPDATE collab_email_drafts
  SET approval_status = 'approved',
      approved_by = p_principal_id,
      approved_principal_id = p_principal_id,
      approved_session_id = p_session_id,
      approved_at = p_approved_at,
      approved_draft_revision = p_draft_revision,
      approval_challenge_id = p_challenge_id,
      approval_content_hash = p_content_hash,
      updated_at = p_approved_at
  WHERE id = p_draft_id
    AND approval_status = 'pending_approval'
    AND content_revision = p_draft_revision;
  GET DIAGNOSTICS approved_count = ROW_COUNT;

  IF approved_count <> 1 THEN
    RAISE EXCEPTION 'draft_state_changed';
  END IF;

  RETURN jsonb_build_object('approved', true);
END;
$function$;

CREATE OR REPLACE FUNCTION public.assign_unscheduled_treatment_queue_item(p_queue_id uuid, p_assigned_to uuid, p_priority text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_queue     RECORD;
    v_user      RECORD;
    v_assignee  RECORD;
    v_old_to    UUID;
    v_old_pri   TEXT;
BEGIN
    -- Get queue item (lock)
    SELECT * INTO v_queue
    FROM public.unscheduled_treatment_queue
    WHERE id = p_queue_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Queue item not found: %', p_queue_id;
    END IF;

    -- Get actor
    SELECT id, full_name, role
    INTO v_user
    FROM public.user_profiles
    WHERE id = auth.uid();

    -- Office access + manager check
    IF NOT user_can_access_office(v_queue.office_id) THEN
        RAISE EXCEPTION 'Access denied: cannot assign for this office';
    END IF;

    IF v_user.role NOT IN ('super_admin','admin','regional_manager','regional_clinical_manager','office_manager') THEN
        RAISE EXCEPTION 'Access denied: only managers can assign queue items';
    END IF;

    -- Validate assignee exists
    SELECT id, full_name INTO v_assignee
    FROM public.user_profiles
    WHERE id = p_assigned_to;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Assignee not found: %', p_assigned_to;
    END IF;

    v_old_to := v_queue.assigned_to;
    v_old_pri := v_queue.priority;

    -- Update
    UPDATE public.unscheduled_treatment_queue
    SET assigned_to = p_assigned_to,
        assigned_by = auth.uid(),
        assigned_at = now(),
        priority = COALESCE(p_priority, priority)
    WHERE id = p_queue_id;

    -- Audit
    INSERT INTO public.unscheduled_treatment_audit_log (
        entity_type, entity_id, office_id, action,
        actor_id, actor_name, old_values, new_values
    ) VALUES (
        'assignment', p_queue_id, v_queue.office_id, 'assigned',
        auth.uid(), v_user.full_name,
        jsonb_build_object('assigned_to', v_old_to::text, 'priority', v_old_pri),
        jsonb_build_object('assigned_to', p_assigned_to::text, 'assignee_name', v_assignee.full_name, 'priority', COALESCE(p_priority, v_old_pri))
    );

    RETURN jsonb_build_object(
        'queue_id', p_queue_id,
        'assigned_to', p_assigned_to,
        'assignee_name', v_assignee.full_name,
        'priority', COALESCE(p_priority, v_old_pri)
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.auto_update_inventory_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.quantity_on_hand <= 0 THEN
    NEW.inv_status := 'out_of_stock';
  ELSIF NEW.quantity_on_hand <= NEW.critically_low_threshold THEN
    NEW.inv_status := 'critically_low';
  ELSIF NEW.quantity_on_hand <= NEW.reorder_level THEN
    NEW.inv_status := 'low';
  ELSE
    NEW.inv_status := 'in_stock';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.bti_audit_trigger_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_action TEXT;
  v_changed_by UUID;
  v_changed_by_name TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'created';
    v_changed_by := NEW.created_by;
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := 'updated';
    v_changed_by := NEW.updated_by;
  ELSIF TG_OP = 'DELETE' THEN
    v_action := 'deleted';
    v_changed_by := OLD.created_by;
  END IF;

  SELECT COALESCE(full_name, '') INTO v_changed_by_name
  FROM public.user_profiles
  WHERE id = v_changed_by
  LIMIT 1;

  IF TG_OP = 'DELETE' THEN
    INSERT INTO public.bone_tissue_audit_log (record_id, action, changed_by, changed_by_name, old_values, new_values)
    VALUES (OLD.id, v_action, v_changed_by, COALESCE(v_changed_by_name, ''), to_jsonb(OLD), NULL);
    RETURN OLD;
  ELSIF TG_OP = 'INSERT' THEN
    INSERT INTO public.bone_tissue_audit_log (record_id, action, changed_by, changed_by_name, old_values, new_values)
    VALUES (NEW.id, v_action, v_changed_by, COALESCE(v_changed_by_name, ''), NULL, to_jsonb(NEW));
  ELSE
    INSERT INTO public.bone_tissue_audit_log (record_id, action, changed_by, changed_by_name, old_values, new_values)
    VALUES (NEW.id, v_action, v_changed_by, COALESCE(v_changed_by_name, ''), to_jsonb(OLD), to_jsonb(NEW));
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.bti_auto_deduct_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_current_stock INTEGER;
BEGIN
  -- Only deduct when status changes TO 'Used'
  IF (TG_OP = 'INSERT' AND NEW.item_status = 'Used') OR
     (TG_OP = 'UPDATE' AND NEW.item_status = 'Used' AND (OLD.item_status IS DISTINCT FROM 'Used')) THEN

    IF NEW.identification_number IS NOT NULL AND NEW.identification_number != '' THEN
      -- Get current stock
      SELECT current_stock INTO v_current_stock
      FROM public.bone_tissue_stock
      WHERE identification_number = NEW.identification_number
        AND (office_id = NEW.office_id OR (office_id IS NULL AND NEW.office_id IS NULL))
      LIMIT 1;

      IF v_current_stock IS NOT NULL AND v_current_stock > 0 THEN
        UPDATE public.bone_tissue_stock
        SET current_stock = GREATEST(0, current_stock - 1),
            updated_at = CURRENT_TIMESTAMP
        WHERE identification_number = NEW.identification_number
          AND (office_id = NEW.office_id OR (office_id IS NULL AND NEW.office_id IS NULL));
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

