CREATE OR REPLACE FUNCTION public.enforce_sender_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF OLD.sender_locked = TRUE THEN
    IF NEW.send_from_email IS DISTINCT FROM OLD.send_from_email
       OR NEW.send_from_account IS DISTINCT FROM OLD.send_from_account
       OR NEW.sender_identity_id IS DISTINCT FROM OLD.sender_identity_id
       OR NEW.provider_account_email IS DISTINCT FROM OLD.provider_account_email
       OR NEW.signature_id IS DISTINCT FROM OLD.signature_id
       OR NEW.signature_version IS DISTINCT FROM OLD.signature_version
    THEN
      INSERT INTO collab_sender_identity_audit (
        event_type, severity, draft_id, agent_name, attempted_sender,
        authorized_sender, violation_rule, rejection_reason, action_taken, http_status
      ) VALUES (
        'REJECT_POST_APPROVAL_CHANGE', 'SECURITY', OLD.id,
        COALESCE(current_setting('app.current_agent', true), 'unknown'),
        NEW.send_from_email, OLD.send_from_email, 'Rule 6',
        'Sender identity or signature locked after approval', 'rejected_409', 409
      );
      RAISE EXCEPTION 'SENDER_LOCKED: sender identity and signature cannot change after approval (draft_id=%)', OLD.id
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.approval_status IN ('approved', 'sent')
     AND OLD.approval_status NOT IN ('approved', 'sent') THEN
    NEW.sender_locked := TRUE;
    NEW.sender_locked_at := NOW();
    NEW.sender_locked_by := COALESCE(current_setting('app.current_agent', true), 'dr_g');
    NEW.sender_lock_reason := NEW.approval_status;
    INSERT INTO collab_sender_identity_audit (
      event_type, severity, draft_id, agent_name, authorized_sender,
      violation_rule, rejection_reason, action_taken, http_status
    ) VALUES (
      'SENDER_LOCKED', 'INFO', NEW.id,
      COALESCE(current_setting('app.current_agent', true), 'dr_g'),
      NEW.send_from_email, 'Rule 6', 'Sender identity and signature locked', 'allowed', 200
    );
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.eod_status_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Stamp submitted_at on first submission
  IF NEW.status = 'pending' AND (OLD.status IS NULL OR OLD.status <> 'pending') THEN
    NEW.submitted_at := now();
  END IF;
  -- Stamp approved_at when approved or re-approved
  IF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status <> 'approved') THEN
    NEW.approved_at := now();
  END IF;
  -- Stamp rejected_at when rejected or rejected_after_approval
  IF NEW.status IN ('rejected', 'rejected_after_approval') AND
     (OLD.status IS NULL OR OLD.status NOT IN ('rejected', 'rejected_after_approval')) THEN
    NEW.rejected_at := now();
  END IF;
  -- Record previous_status and status_changed_at on any status change
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    NEW.previous_status   := OLD.status;
    NEW.status_changed_at := now();
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.fdi_auto_update_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.current_qty = 0 THEN
    NEW.status := 'Out of Stock'::public.front_desk_item_status;
  ELSIF NEW.current_qty <= (NEW.min_required / 2) THEN
    NEW.status := 'Critically Low'::public.front_desk_item_status;
  ELSIF NEW.current_qty <= NEW.min_required THEN
    NEW.status := 'Low'::public.front_desk_item_status;
  ELSE
    NEW.status := 'In Stock'::public.front_desk_item_status;
  END IF;
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$function$;

