CREATE OR REPLACE FUNCTION public.fn_audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action       TEXT;
  v_old_values   JSONB := NULL;
  v_new_values   JSONB := NULL;
  v_record_id    UUID := NULL;
  v_user_id      UUID := NULL;
  v_changed_fields TEXT[] := NULL;
BEGIN
  -- Determine action type
  IF TG_OP = 'INSERT' THEN
    v_action     := 'INSERT';
    v_new_values := to_jsonb(NEW);
    -- Try to extract id field
    BEGIN v_record_id := (to_jsonb(NEW)->>'id')::UUID; EXCEPTION WHEN OTHERS THEN NULL; END;
  ELSIF TG_OP = 'UPDATE' THEN
    v_action     := 'UPDATE';
    v_old_values := to_jsonb(OLD);
    v_new_values := to_jsonb(NEW);
    BEGIN v_record_id := (to_jsonb(NEW)->>'id')::UUID; EXCEPTION WHEN OTHERS THEN NULL; END;
    -- Capture which fields changed
    SELECT array_agg(key)
    INTO v_changed_fields
    FROM jsonb_each(to_jsonb(NEW)) n
    JOIN jsonb_each(to_jsonb(OLD)) o USING (key)
    WHERE n.value IS DISTINCT FROM o.value;
  ELSIF TG_OP = 'DELETE' THEN
    v_action     := 'DELETE';
    v_old_values := to_jsonb(OLD);
    BEGIN v_record_id := (to_jsonb(OLD)->>'id')::UUID; EXCEPTION WHEN OTHERS THEN NULL; END;
  END IF;

  -- Attempt to get current user from auth.uid()
  BEGIN
    v_user_id := auth.uid();
  EXCEPTION WHEN OTHERS THEN
    v_user_id := NULL;
  END;

  -- Insert audit record (fire-and-forget, never block the original operation)
  BEGIN
    INSERT INTO public.audit_logs (
      user_id,
      action,
      table_name,
      record_id,
      old_values,
      new_values,
      changed_fields,
      created_at
    ) VALUES (
      v_user_id,
      v_action,
      TG_TABLE_NAME,
      v_record_id,
      v_old_values,
      v_new_values,
      v_changed_fields,
      NOW()
    );
  EXCEPTION WHEN OTHERS THEN
    -- Never let audit failure block the main operation
    NULL;
  END;

  -- Return appropriate row
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$function$;

