CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    INSERT INTO public.user_profiles (id, email, full_name, role)
    VALUES (
        NEW.id,
        NEW.email,
        COALESCE(NEW.raw_user_meta_data->>'full_name', split_part(NEW.email, '@', 1)),
        COALESCE(NEW.raw_user_meta_data->>'role', 'staff')::public.user_role
    )
    ON CONFLICT (id) DO NOTHING;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.implant_auto_deduct_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF NEW.item_status = 'used' AND NEW.implant_inventory_id IS NOT NULL THEN
    UPDATE public.implant_inventory
    SET
      quantity_in_stock = GREATEST(0, quantity_in_stock - 1),
      updated_at = now()
    WHERE id = NEW.implant_inventory_id;
  END IF;
  RETURN NEW;
END;
$function$;

