CREATE OR REPLACE FUNCTION public.log_unscheduled_treatment_contact(p_queue_id uuid, p_outcome text, p_notes text DEFAULT NULL::text, p_follow_up_date date DEFAULT NULL::date, p_scheduled_date date DEFAULT NULL::date, p_scheduled_appt_id text DEFAULT NULL::text, p_treatment_value numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_queue         RECORD;
    v_user          RECORD;
    v_contact_id    UUID;
    v_new_status    TEXT;
    v_old_status    TEXT;
BEGIN
    -- Validate outcome
    IF p_outcome NOT IN (
        'scheduled','left_message','no_answer','not_interested',
        'wants_callback','financial_concern','insurance_issue',
        'already_scheduled','wrong_number','do_not_call','other'
    ) THEN
        RAISE EXCEPTION 'Invalid outcome: %', p_outcome;
    END IF;

    -- Get queue item (lock row)
    SELECT * INTO v_queue
    FROM public.unscheduled_treatment_queue
    WHERE id = p_queue_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Queue item not found: %', p_queue_id;
    END IF;

    -- Get current user info
    SELECT id, full_name, office_id, role
    INTO v_user
    FROM public.user_profiles
    WHERE id = auth.uid();

    IF NOT FOUND THEN
        RAISE EXCEPTION 'User not found';
    END IF;

    -- Office access check
    IF NOT user_can_access_office(v_queue.office_id) THEN
        RAISE EXCEPTION 'Access denied: cannot log contact for this office';
    END IF;

    -- Determine new queue status
    v_old_status := v_queue.queue_status;
    v_new_status := CASE p_outcome
        WHEN 'scheduled'         THEN 'scheduled'
        WHEN 'already_scheduled' THEN 'scheduled'
        WHEN 'do_not_call'       THEN 'do_not_call'
        WHEN 'not_interested'    THEN 'dismissed'
        WHEN 'wants_callback'    THEN 'deferred'
        WHEN 'financial_concern' THEN 'deferred'
        WHEN 'insurance_issue'   THEN 'deferred'
        WHEN 'left_message'      THEN 'in_progress'
        WHEN 'no_answer'         THEN 'in_progress'
        WHEN 'wrong_number'      THEN 'in_progress'
        WHEN 'other'             THEN CASE
            WHEN p_follow_up_date IS NOT NULL THEN 'deferred'
            ELSE 'in_progress'
        END
    END;

    -- Insert contact record
    INSERT INTO public.unscheduled_treatment_contacts (
        queue_id, office_id, dentrix_patient_id,
        contacted_by, contacted_by_name, contact_at, contact_date,
        outcome, notes, follow_up_date,
        scheduled_date, scheduled_appt_id, treatment_value_discussed
    ) VALUES (
        p_queue_id, v_queue.office_id, v_queue.dentrix_patient_id,
        auth.uid(), v_user.full_name, now(), CURRENT_DATE,
        p_outcome, p_notes, p_follow_up_date,
        p_scheduled_date, p_scheduled_appt_id, p_treatment_value
    )
    RETURNING id INTO v_contact_id;

    -- Update queue item
    UPDATE public.unscheduled_treatment_queue
    SET contact_attempt_count = contact_attempt_count + 1,
        last_contact_at = now(),
        last_contact_outcome = p_outcome,
        queue_status = v_new_status,
        follow_up_date = COALESCE(p_follow_up_date, follow_up_date),
        last_scheduled_date = CASE
            WHEN p_outcome IN ('scheduled','already_scheduled') THEN p_scheduled_date
            ELSE last_scheduled_date
        END,
        last_scheduled_appt_id = CASE
            WHEN p_outcome IN ('scheduled','already_scheduled') THEN p_scheduled_appt_id
            ELSE last_scheduled_appt_id
        END
    WHERE id = p_queue_id;

    -- Audit log
    INSERT INTO public.unscheduled_treatment_audit_log (
        entity_type, entity_id, office_id, action,
        actor_id, actor_name, old_values, new_values, metadata
    ) VALUES (
        'contact', v_contact_id, v_queue.office_id, 'outcome_logged',
        auth.uid(), v_user.full_name,
        jsonb_build_object('queue_status', v_old_status, 'contact_attempt_count', v_queue.contact_attempt_count),
        jsonb_build_object('queue_status', v_new_status, 'contact_attempt_count', v_queue.contact_attempt_count + 1, 'outcome', p_outcome),
        jsonb_build_object('notes', p_notes, 'follow_up_date', p_follow_up_date::text, 'scheduled_date', p_scheduled_date::text)
    );

    -- Status change audit if changed
    IF v_old_status != v_new_status THEN
        INSERT INTO public.unscheduled_treatment_audit_log (
            entity_type, entity_id, office_id, action,
            actor_id, actor_name, old_values, new_values
        ) VALUES (
            'queue_item', p_queue_id, v_queue.office_id, 'status_changed',
            auth.uid(), v_user.full_name,
            jsonb_build_object('queue_status', v_old_status),
            jsonb_build_object('queue_status', v_new_status)
        );
    END IF;

    RETURN jsonb_build_object(
        'contact_id', v_contact_id,
        'queue_id', p_queue_id,
        'old_status', v_old_status,
        'new_status', v_new_status,
        'contact_attempt_count', v_queue.contact_attempt_count + 1
    );
END;
$function$;

