CREATE OR REPLACE FUNCTION public.preview_import_preflight(p_batch_id uuid, p_cardholder_map jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_batch          record;
  v_result         jsonb;
  v_corp_cards     text[] := ARRAY['1001','1002','1003','1077'];
BEGIN
  -- 0. Access control
  IF NOT public.is_admin_or_above_expense() THEN
    RAISE EXCEPTION 'Preview requires admin or above role';
  END IF;

  -- 1. Validate batch
  SELECT * INTO v_batch
  FROM public.expense_import_batches
  WHERE id = p_batch_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Batch not found', 'batch_id', p_batch_id);
  END IF;

  IF v_batch.approval_status IN ('approved','posted','rolled_back') THEN
    RETURN jsonb_build_object(
      'error', format('Batch already in terminal state: %s', v_batch.approval_status),
      'batch_id', p_batch_id
    );
  END IF;

  -- 2. Full read-only classification via CTEs
  WITH

  batch_rows AS (
    SELECT
      r.id,
      r.reference_number,
      r.transaction_date,
      r.amount,
      r.merchant_name,
      r.cardholder_name,
      RIGHT(REGEXP_REPLACE(r.card_last4, '\D', '', 'g'), 4) AS norm_card,
      LOWER(REGEXP_REPLACE(r.merchant_name, '[^a-zA-Z0-9]', '', 'g')) AS norm_merchant,
      CASE
        WHEN r.transaction_date IS NULL
          OR r.amount IS NULL
          OR r.card_last4 IS NULL
          OR r.merchant_name IS NULL
          OR RIGHT(REGEXP_REPLACE(r.card_last4, '\D', '', 'g'), 4) = ''
          OR LOWER(REGEXP_REPLACE(r.merchant_name, '[^a-zA-Z0-9]', '', 'g')) = ''
        THEN NULL
        ELSE encode(sha256((
          r.transaction_date::date::text || '|' ||
          ROUND(ABS(r.amount) * 100)::bigint::text || '|' ||
          RIGHT(REGEXP_REPLACE(r.card_last4, '\D', '', 'g'), 4) || '|' ||
          LOWER(REGEXP_REPLACE(r.merchant_name, '[^a-zA-Z0-9]', '', 'g'))
        )::bytea), 'hex')
      END AS computed_fp
    FROM public.amex_raw_transactions r
    WHERE r.import_batch_id = p_batch_id
      AND r.source_type = 'amex_statement_import'
      AND (r.review_status IS NULL OR r.review_status = 'staged')
  ),

  with_failed AS (
    SELECT *, (computed_fp IS NULL) AS is_failed
    FROM batch_rows
  ),

  ref_exp_match AS (
    SELECT b.id AS raw_id,
      COUNT(*) AS candidate_count,
      jsonb_agg(jsonb_build_object(
        'merchant', e.merchant_name,
        'amount', e.amount,
        'date', e.expense_date,
        'card_last4', RIGHT(REGEXP_REPLACE(e.card_last4, '\D', '', 'g'), 4),
        'source_type', e.source_type
      ) ORDER BY e.expense_date DESC) AS candidate_samples
    FROM with_failed b
    JOIN public.expenses e
      ON e.source_reference_id = b.reference_number
     AND e.source_type IN ('amex_api', 'amex_statement_import')
     AND e.expense_status = 'posted'
     AND e.source_tab IS DISTINCT FROM 'Banking'
    WHERE NOT b.is_failed AND b.reference_number IS NOT NULL
    GROUP BY b.id
  ),

  ref_raw_match AS (
    SELECT b.id AS raw_id,
      COUNT(*) AS candidate_count,
      jsonb_agg(jsonb_build_object(
        'merchant', r2.merchant_name,
        'amount', r2.amount,
        'date', r2.transaction_date,
        'card_last4', RIGHT(REGEXP_REPLACE(r2.card_last4, '\D', '', 'g'), 4),
        'source_type', r2.source_type
      ) ORDER BY r2.transaction_date DESC) AS candidate_samples
    FROM with_failed b
    JOIN public.amex_raw_transactions r2
      ON r2.reference_number = b.reference_number
     AND r2.import_batch_id IS DISTINCT FROM p_batch_id
     AND r2.reference_number IS NOT NULL
    WHERE NOT b.is_failed
      AND b.reference_number IS NOT NULL
      AND b.id NOT IN (SELECT raw_id FROM ref_exp_match)
    GROUP BY b.id
  ),

  fp_match AS (
    SELECT b.id AS raw_id,
      COUNT(DISTINCT e.id) AS candidate_count,
      jsonb_agg(DISTINCT jsonb_build_object(
        'merchant', e.merchant_name,
        'amount', e.amount,
        'date', e.expense_date,
        'card_last4', RIGHT(REGEXP_REPLACE(e.card_last4, '\D', '', 'g'), 4),
        'source_type', e.source_type
      )) AS candidate_samples
    FROM with_failed b
    JOIN public.expenses e
      ON e.source_fingerprint = b.computed_fp
     AND e.source_type IN ('amex_api', 'amex_statement_import')
     AND e.expense_status = 'posted'
     AND e.source_tab IS DISTINCT FROM 'Banking'
    WHERE NOT b.is_failed
      AND b.computed_fp IS NOT NULL
      AND b.amount >= 0
      AND b.id NOT IN (SELECT raw_id FROM ref_exp_match)
      AND b.id NOT IN (SELECT raw_id FROM ref_raw_match)
    GROUP BY b.id
  ),

  fuzzy_match AS (
    SELECT b.id AS raw_id,
      COUNT(DISTINCT e.id) AS candidate_count,
      jsonb_agg(DISTINCT jsonb_build_object(
        'merchant', e.merchant_name,
        'amount', e.amount,
        'date', e.expense_date,
        'card_last4', RIGHT(REGEXP_REPLACE(e.card_last4, '\D', '', 'g'), 4),
        'source_type', e.source_type
      )) AS candidate_samples
    FROM with_failed b
    JOIN public.expenses e
      ON ABS(b.transaction_date::date - e.expense_date::date) <= 1
     AND ROUND(ABS(b.amount) * 100)::bigint = ROUND(ABS(e.amount) * 100)::bigint
     AND b.norm_card = RIGHT(REGEXP_REPLACE(e.card_last4, '\D', '', 'g'), 4)
     AND b.norm_merchant = LOWER(REGEXP_REPLACE(e.merchant_name, '[^a-zA-Z0-9]', '', 'g'))
     AND e.source_type IN ('amex_api', 'amex_statement_import')
     AND e.expense_status = 'posted'
     AND e.source_tab IS DISTINCT FROM 'Banking'
    WHERE NOT b.is_failed
      AND b.amount >= 0
      AND b.id NOT IN (SELECT raw_id FROM ref_exp_match)
      AND b.id NOT IN (SELECT raw_id FROM ref_raw_match)
      AND b.id NOT IN (SELECT raw_id FROM fp_match)
    GROUP BY b.id
  ),

  intra_batch AS (
    SELECT computed_fp, COUNT(*) AS collision_count
    FROM with_failed
    WHERE NOT is_failed AND computed_fp IS NOT NULL
    GROUP BY computed_fp
    HAVING COUNT(*) > 1
  ),

  neg_dup_evidence AS (
    SELECT
      b.id AS raw_id,
      CASE
        WHEN rem.raw_id IS NOT NULL THEN 'ref_to_expense'
        WHEN rrm.raw_id IS NOT NULL THEN 'ref_to_raw'
        WHEN nfp.candidate_count > 0 THEN 'fingerprint_to_expense'
        ELSE NULL
      END AS neg_dup_match_type,
      COALESCE(rem.candidate_count, rrm.candidate_count, nfp.candidate_count, 0) AS neg_dup_count,
      COALESCE(rem.candidate_samples, rrm.candidate_samples, nfp.candidate_samples) AS neg_dup_samples
    FROM with_failed b
    LEFT JOIN ref_exp_match rem ON rem.raw_id = b.id
    LEFT JOIN ref_raw_match rrm ON rrm.raw_id = b.id
    LEFT JOIN LATERAL (
      SELECT
        COUNT(DISTINCT e.id) AS candidate_count,
        jsonb_agg(DISTINCT jsonb_build_object(
          'merchant', e.merchant_name,
          'amount', e.amount,
          'date', e.expense_date,
          'card_last4', RIGHT(REGEXP_REPLACE(e.card_last4, '\D', '', 'g'), 4),
          'source_type', e.source_type
        )) AS candidate_samples
      FROM public.expenses e
      WHERE e.source_fingerprint = b.computed_fp
        AND e.source_type IN ('amex_api', 'amex_statement_import')
        AND e.expense_status = 'posted'
        AND e.source_tab IS DISTINCT FROM 'Banking'
      HAVING COUNT(*) > 0
    ) nfp ON rem.raw_id IS NULL AND rrm.raw_id IS NULL
    WHERE NOT b.is_failed AND b.amount < 0
  ),

  classified AS (
    SELECT
      b.id,
      b.transaction_date,
      b.amount,
      b.norm_card,
      b.merchant_name,
      b.cardholder_name,
      b.computed_fp,
      b.is_failed,

      CASE
        WHEN b.is_failed THEN 'failed'
        WHEN rem.raw_id IS NOT NULL THEN 'exact_duplicate'
        WHEN rrm.raw_id IS NOT NULL THEN 'exact_duplicate'
        WHEN b.amount < 0 THEN 'credit_refund'
        WHEN fpm.raw_id IS NOT NULL THEN 'possible_duplicate'
        WHEN fzm.raw_id IS NOT NULL THEN 'possible_duplicate'
        WHEN NOT (p_cardholder_map ? b.norm_card)
             OR b.norm_card = ANY(v_corp_cards)
          THEN 'needs_mapping'
        ELSE 'ready_for_review'
      END AS predicted_status,

      CASE
        WHEN rem.raw_id IS NOT NULL THEN 'exact'
        WHEN rrm.raw_id IS NOT NULL THEN 'exact'
        WHEN b.amount < 0 AND nde.neg_dup_match_type IS NOT NULL THEN 'cross_source'
        WHEN fpm.raw_id IS NOT NULL THEN 'cross_source'
        WHEN fzm.raw_id IS NOT NULL THEN 'possible'
        ELSE 'none'
      END AS predicted_dup_status,

      CASE
        WHEN rem.raw_id IS NOT NULL THEN 'ref_to_expense'
        WHEN rrm.raw_id IS NOT NULL THEN 'ref_to_raw'
        WHEN b.amount < 0 THEN nde.neg_dup_match_type
        WHEN fpm.raw_id IS NOT NULL THEN 'fingerprint_to_expense'
        WHEN fzm.raw_id IS NOT NULL THEN 'fuzzy_to_expense'
        ELSE NULL
      END AS dup_match_type,

      CASE
        WHEN rem.raw_id IS NOT NULL THEN rem.candidate_count
        WHEN rrm.raw_id IS NOT NULL THEN rrm.candidate_count
        WHEN b.amount < 0 THEN COALESCE(nde.neg_dup_count, 0)
        WHEN fpm.raw_id IS NOT NULL THEN fpm.candidate_count
        WHEN fzm.raw_id IS NOT NULL THEN fzm.candidate_count
        ELSE 0
      END AS dup_candidate_count,

      CASE
        WHEN rem.raw_id IS NOT NULL THEN rem.candidate_samples
        WHEN rrm.raw_id IS NOT NULL THEN rrm.candidate_samples
        WHEN b.amount < 0 THEN nde.neg_dup_samples
        WHEN fpm.raw_id IS NOT NULL THEN fpm.candidate_samples
        WHEN fzm.raw_id IS NOT NULL THEN fzm.candidate_samples
        ELSE NULL
      END AS dup_candidate_samples,

      CASE
        WHEN b.is_failed THEN NULL
        ELSE p_cardholder_map -> b.norm_card ->> 'office'
      END AS predicted_office,

      CASE WHEN b.amount < 0 THEN
        CASE
          WHEN b.merchant_name ~* '(MOBILE PAYMENT|AUTOPAY PAYMENT).*THANK YOU'
            THEN 'statement_payment'
          WHEN b.merchant_name ~* '^AMEX\s'
               OR b.merchant_name ~* 'Business Platinum.*Credit'
            THEN 'amex_benefit_credit'
          WHEN b.merchant_name ~* '(CR ADJ|ADJ PURCHASE).*FIN(ANCE)?\s*CH'
            THEN 'amex_adjustment'
          WHEN b.merchant_name = 'SERVICE' AND ABS(b.amount) <= 5.00
            THEN 'amex_service_credit'
          ELSE 'vendor_credit_refund'
        END
      ELSE NULL END AS credit_subtype

    FROM with_failed b
    LEFT JOIN ref_exp_match rem ON rem.raw_id = b.id
    LEFT JOIN ref_raw_match rrm ON rrm.raw_id = b.id
    LEFT JOIN fp_match fpm ON fpm.raw_id = b.id
    LEFT JOIN fuzzy_match fzm ON fzm.raw_id = b.id
    LEFT JOIN neg_dup_evidence nde ON nde.raw_id = b.id
  ),

  status_counts AS (
    SELECT jsonb_object_agg(predicted_status, cnt) AS val
    FROM (SELECT predicted_status, COUNT(*) AS cnt FROM classified GROUP BY 1) s
  ),

  dup_counts AS (
    SELECT jsonb_object_agg(predicted_dup_status, cnt) AS val
    FROM (SELECT predicted_dup_status, COUNT(*) AS cnt FROM classified GROUP BY 1) s
  ),

  credit_counts AS (
    SELECT jsonb_object_agg(credit_subtype, cnt) AS val
    FROM (SELECT credit_subtype, COUNT(*) AS cnt
          FROM classified WHERE credit_subtype IS NOT NULL GROUP BY 1) s
  ),

  office_counts AS (
    SELECT jsonb_object_agg(COALESCE(predicted_office, 'UNMAPPED'), cnt) AS val
    FROM (SELECT predicted_office, COUNT(*) AS cnt
          FROM classified WHERE NOT is_failed GROUP BY 1) s
  ),

  examples AS (
    SELECT jsonb_object_agg(predicted_status, rows) AS val
    FROM (
      SELECT predicted_status,
        jsonb_agg(jsonb_build_object(
          'merchant', merchant_name,
          'amount', amount,
          'date', transaction_date,
          'card_last4', norm_card,
          'predicted_dup_status', predicted_dup_status,
          'dup_match_type', dup_match_type,
          'dup_candidate_count', dup_candidate_count,
          'dup_candidate_samples', dup_candidate_samples,
          'predicted_office', predicted_office,
          'credit_subtype', credit_subtype
        ) ORDER BY ABS(amount) DESC) AS rows
      FROM (
        SELECT *, ROW_NUMBER() OVER (
          PARTITION BY predicted_status ORDER BY ABS(amount) DESC
        ) AS rn
        FROM classified
      ) ranked
      WHERE rn <= 5
      GROUP BY predicted_status
    ) s
  ),

  intra_summary AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'fingerprint', computed_fp,
      'count', collision_count
    ) ORDER BY collision_count DESC), '[]'::jsonb) AS val
    FROM (SELECT * FROM intra_batch LIMIT 10) ib
  ),

  blockers AS (
    SELECT COALESCE(jsonb_agg(blocker), '[]'::jsonb) AS val
    FROM (
      SELECT jsonb_build_object(
        'type', 'failed_rows', 'count', COUNT(*)
      ) AS blocker
      FROM classified WHERE predicted_status = 'failed'
      HAVING COUNT(*) > 0
      UNION ALL
      SELECT jsonb_build_object(
        'type', 'unmapped_cards', 'count', COUNT(*),
        'cards', jsonb_agg(DISTINCT norm_card)
      )
      FROM classified
      WHERE predicted_status = 'needs_mapping'
        AND NOT (p_cardholder_map ? norm_card)
      HAVING COUNT(*) > 0
      UNION ALL
      SELECT jsonb_build_object(
        'type', 'corp_cards_need_office', 'count', COUNT(*)
      )
      FROM classified
      WHERE predicted_status = 'needs_mapping'
        AND (p_cardholder_map ? norm_card)
      HAVING COUNT(*) > 0
    ) b
  )

  SELECT jsonb_build_object(
    'batch_id',              p_batch_id,
    'batch_filename',        v_batch.import_filename,
    'batch_statement_month', v_batch.statement_month,
    'batch_status',          v_batch.approval_status,
    'total_rows',            (SELECT COUNT(*) FROM batch_rows),
    'counts_by_status',      (SELECT val FROM status_counts),
    'counts_by_dup_status',  (SELECT val FROM dup_counts),
    'counts_by_credit_type', COALESCE((SELECT val FROM credit_counts), '{}'::jsonb),
    'counts_by_office',      COALESCE((SELECT val FROM office_counts), '{}'::jsonb),
    'examples_by_status',    COALESCE((SELECT val FROM examples), '{}'::jsonb),
    'intra_batch_collisions',(SELECT val FROM intra_summary),
    'blockers',              (SELECT val FROM blockers),
    'safe_to_proceed',       (
      NOT EXISTS (SELECT 1 FROM classified WHERE predicted_status = 'failed')
      AND (SELECT COUNT(*) FROM batch_rows) > 0
    ),
    'cardholder_map_cards',  (SELECT COUNT(*) FROM jsonb_object_keys(p_cardholder_map) k)
  ) INTO v_result;

  RETURN v_result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.reconcile_gusto_expenses(p_start_date date, p_end_date date, p_office_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_payroll_source_total   numeric := 0;
  v_payroll_expense_total  numeric := 0;
  v_contractor_source_total  numeric := 0;
  v_contractor_expense_total numeric := 0;
  v_benefit_source_total   numeric := 0;
  v_benefit_expense_total  numeric := 0;
  v_warnings               jsonb   := '[]'::jsonb;
  v_threshold              numeric := 0.01;
BEGIN
  -- ── Payroll: source total from gusto_payroll_runs ─────────────────────────
  SELECT COALESCE(SUM(total_net_pay), 0)
    INTO v_payroll_source_total
    FROM public.gusto_payroll_runs
    WHERE processed = true
      AND (reversed IS NULL OR reversed = false)
      AND (needs_reprocessing IS NULL OR needs_reprocessing = false)
      AND check_date BETWEEN p_start_date AND p_end_date;

  -- ── Payroll: expense total from gusto_expense_facts ───────────────────────
  SELECT COALESCE(SUM(expense_amount), 0)
    INTO v_payroll_expense_total
    FROM public.gusto_expense_facts
    WHERE expense_category = 'Payroll'
      AND expense_date BETWEEN p_start_date AND p_end_date
      AND (p_office_id IS NULL OR office_id = p_office_id);

  -- ── Contractors: source total ─────────────────────────────────────────────
  SELECT COALESCE(SUM(total_amount), 0)
    INTO v_contractor_source_total
    FROM public.gusto_contractor_payments
    WHERE (cancelled IS NULL OR cancelled = false)
      AND (funded IS NULL OR funded = true)
      AND check_date BETWEEN p_start_date AND p_end_date;

  -- ── Contractors: expense total ────────────────────────────────────────────
  SELECT COALESCE(SUM(expense_amount), 0)
    INTO v_contractor_expense_total
    FROM public.gusto_expense_facts
    WHERE expense_category = 'Contractors Paid'
      AND expense_date BETWEEN p_start_date AND p_end_date
      AND (p_office_id IS NULL OR office_id = p_office_id);

  -- ── Check mismatches ──────────────────────────────────────────────────────
  IF ABS(v_payroll_source_total - v_payroll_expense_total) > v_threshold THEN
    v_warnings := v_warnings || jsonb_build_object(
      'category',      'Payroll',
      'source_total',  v_payroll_source_total,
      'expense_total', v_payroll_expense_total,
      'variance',      v_payroll_source_total - v_payroll_expense_total,
      'message',       'Payroll expense total does not match processed Gusto payroll runs total'
    );
  END IF;

  IF ABS(v_contractor_source_total - v_contractor_expense_total) > v_threshold THEN
    v_warnings := v_warnings || jsonb_build_object(
      'category',      'Contractors Paid',
      'source_total',  v_contractor_source_total,
      'expense_total', v_contractor_expense_total,
      'variance',      v_contractor_source_total - v_contractor_expense_total,
      'message',       'Contractors Paid expense total does not match Gusto contractor payments total'
    );
  END IF;

  RETURN jsonb_build_object(
    'period_start',              p_start_date,
    'period_end',                p_end_date,
    'payroll_source_total',      v_payroll_source_total,
    'payroll_expense_total',     v_payroll_expense_total,
    'contractor_source_total',   v_contractor_source_total,
    'contractor_expense_total',  v_contractor_expense_total,
    'benefit_source_total',      v_benefit_source_total,
    'benefit_expense_total',     v_benefit_expense_total,
    'warnings',                  v_warnings,
    'is_reconciled',             (jsonb_array_length(v_warnings) = 0),
    'checked_at',                now()
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_office_id_by_name(office_name_input text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT id
  FROM public.offices
  WHERE LOWER(TRIM(name)) = LOWER(TRIM(office_name_input))
    AND is_active = true
  LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

