CREATE OR REPLACE FUNCTION public.sync_gusto_expense_facts()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_inserted   integer := 0;
  v_updated    integer := 0;
  v_skipped    integer := 0;
  v_errors     jsonb   := '[]'::jsonb;
  v_run        record;
  v_contractor record;
  v_office_id  uuid;
  v_office_name text;
  v_expense_id text;
BEGIN
  -- ── A. Payroll Runs → "Payroll" expense category ──────────────────────────
  -- Only processed=true, reversed=false, needs_reprocessing=false
  FOR v_run IN
    SELECT
      gpr.id,
      gpr.check_date,
      gpr.pay_period_start,
      gpr.pay_period_end,
      gpr.total_net_pay,
      gpr.total_payable_tax,
      gpr.total_reimbursement,
      gpr.total_debit_amount
    FROM public.gusto_payroll_runs gpr
    WHERE gpr.processed = true
      AND (gpr.reversed IS NULL OR gpr.reversed = false)
      AND (gpr.needs_reprocessing IS NULL OR gpr.needs_reprocessing = false)
      AND (gpr.processing IS NULL OR gpr.processing = false)
      AND gpr.check_date IS NOT NULL
  LOOP
    BEGIN
      -- Resolve office: use first crosswalk mapping for this run, else null
      SELECT gpc.office_id, o.name
        INTO v_office_id, v_office_name
        FROM public.gusto_provider_crosswalk gpc
        LEFT JOIN public.offices o ON o.id = gpc.office_id
        WHERE gpc.active = true
          AND gpc.mapping_status = 'matched'
        LIMIT 1;

      -- ── Payroll (net pay / wages) ──────────────────────────────────────
      IF v_run.total_net_pay IS NOT NULL AND v_run.total_net_pay > 0 THEN
        v_expense_id := 'gpr_payroll_' || v_run.id::text;
        INSERT INTO public.gusto_expense_facts (
          id, source_type, source_table, source_id,
          expense_category, expense_subcategory, expense_source,
          expense_amount, expense_date,
          office_id, office_name, office_mapping_status,
          gusto_run_id, pay_period_start, pay_period_end,
          created_at, updated_at
        ) VALUES (
          v_expense_id, 'gusto_payroll', 'gusto_payroll_runs', v_run.id::text,
          'Payroll', 'Employee Wages / Net Pay', 'gusto_payroll',
          v_run.total_net_pay, v_run.check_date,
          v_office_id, v_office_name,
          CASE WHEN v_office_id IS NULL THEN 'unassigned' ELSE 'resolved' END,
          v_run.id, v_run.pay_period_start, v_run.pay_period_end,
          now(), now()
        )
        ON CONFLICT (source_table, source_id, expense_category) DO UPDATE SET
          expense_amount        = EXCLUDED.expense_amount,
          expense_date          = EXCLUDED.expense_date,
          office_id             = EXCLUDED.office_id,
          office_name           = EXCLUDED.office_name,
          office_mapping_status = EXCLUDED.office_mapping_status,
          pay_period_start      = EXCLUDED.pay_period_start,
          pay_period_end        = EXCLUDED.pay_period_end,
          updated_at            = now();
        v_inserted := v_inserted + 1;
      END IF;

      -- ── Payroll Taxes ──────────────────────────────────────────────────
      IF v_run.total_payable_tax IS NOT NULL AND v_run.total_payable_tax > 0 THEN
        v_expense_id := 'gpr_taxes_' || v_run.id::text;
        INSERT INTO public.gusto_expense_facts (
          id, source_type, source_table, source_id,
          expense_category, expense_subcategory, expense_source,
          expense_amount, expense_date,
          office_id, office_name, office_mapping_status,
          gusto_run_id, pay_period_start, pay_period_end,
          created_at, updated_at
        ) VALUES (
          v_expense_id, 'gusto_payroll', 'gusto_payroll_runs', v_run.id::text,
          'Payroll Taxes', 'Employer Payroll Taxes', 'gusto_payroll',
          v_run.total_payable_tax, v_run.check_date,
          v_office_id, v_office_name,
          CASE WHEN v_office_id IS NULL THEN 'unassigned' ELSE 'resolved' END,
          v_run.id, v_run.pay_period_start, v_run.pay_period_end,
          now(), now()
        )
        ON CONFLICT (source_table, source_id, expense_category) DO UPDATE SET
          expense_amount        = EXCLUDED.expense_amount,
          expense_date          = EXCLUDED.expense_date,
          office_id             = EXCLUDED.office_id,
          office_name           = EXCLUDED.office_name,
          office_mapping_status = EXCLUDED.office_mapping_status,
          updated_at            = now();
        v_inserted := v_inserted + 1;
      END IF;

      -- ── Benefit Paid (reimbursements from payroll run as proxy) ────────
      IF v_run.total_reimbursement IS NOT NULL AND v_run.total_reimbursement > 0 THEN
        v_expense_id := 'gpr_benefits_' || v_run.id::text;
        INSERT INTO public.gusto_expense_facts (
          id, source_type, source_table, source_id,
          expense_category, expense_subcategory, expense_source,
          expense_amount, expense_date,
          office_id, office_name, office_mapping_status,
          gusto_run_id, pay_period_start, pay_period_end,
          created_at, updated_at
        ) VALUES (
          v_expense_id, 'gusto_payroll', 'gusto_payroll_runs', v_run.id::text,
          'Benefit Paid', 'Employer Benefit Contributions', 'gusto_payroll',
          v_run.total_reimbursement, v_run.check_date,
          v_office_id, v_office_name,
          CASE WHEN v_office_id IS NULL THEN 'unassigned' ELSE 'resolved' END,
          v_run.id, v_run.pay_period_start, v_run.pay_period_end,
          now(), now()
        )
        ON CONFLICT (source_table, source_id, expense_category) DO UPDATE SET
          expense_amount        = EXCLUDED.expense_amount,
          expense_date          = EXCLUDED.expense_date,
          office_id             = EXCLUDED.office_id,
          office_name           = EXCLUDED.office_name,
          office_mapping_status = EXCLUDED.office_mapping_status,
          updated_at            = now();
        v_inserted := v_inserted + 1;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors || jsonb_build_object(
        'run_id', v_run.id,
        'error', SQLERRM
      );
    END;
  END LOOP;

  -- ── B. Contractor Payments → "Contractors Paid" expense category ──────────
  -- Only funded=true, cancelled=false
  FOR v_contractor IN
    SELECT
      gcp.id,
      gcp.check_date,
      gcp.total_amount,
      gcp.contractor_name,
      gcp.contractor_display_name
    FROM public.gusto_contractor_payments gcp
    WHERE (gcp.cancelled IS NULL OR gcp.cancelled = false)
      AND (gcp.funded IS NULL OR gcp.funded = true)
      AND gcp.total_amount IS NOT NULL
      AND gcp.total_amount > 0
      AND gcp.check_date IS NOT NULL
  LOOP
    BEGIN
      v_expense_id := 'gcp_contractors_' || v_contractor.id;
      INSERT INTO public.gusto_expense_facts (
        id, source_type, source_table, source_id,
        expense_category, expense_subcategory, expense_source,
        expense_amount, expense_date,
        office_id, office_name, office_mapping_status,
        gusto_employee_name,
        created_at, updated_at
      ) VALUES (
        v_expense_id, 'gusto_payroll', 'gusto_contractor_payments', v_contractor.id,
        'Contractors Paid',
        COALESCE(v_contractor.contractor_display_name, v_contractor.contractor_name, 'Contractor'),
        'gusto_payroll',
        v_contractor.total_amount, v_contractor.check_date,
        NULL, NULL, 'unassigned',
        COALESCE(v_contractor.contractor_display_name, v_contractor.contractor_name),
        now(), now()
      )
      ON CONFLICT (source_table, source_id, expense_category) DO UPDATE SET
        expense_amount   = EXCLUDED.expense_amount,
        expense_date     = EXCLUDED.expense_date,
        updated_at       = now();
      v_inserted := v_inserted + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors || jsonb_build_object(
        'contractor_id', v_contractor.id,
        'error', SQLERRM
      );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'inserted', v_inserted,
    'updated',  v_updated,
    'skipped',  v_skipped,
    'errors',   v_errors,
    'synced_at', now()
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_own_staff_directory_photo(p_staff_directory_id uuid, p_photo_storage_path text, p_photo_uploaded_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_email TEXT;
  v_matched    BOOLEAN := FALSE;
  v_result     JSONB;
BEGIN
  -- Get the authenticated user's email
  SELECT email INTO v_user_email
  FROM auth.users
  WHERE id = auth.uid();

  IF v_user_email IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Verify the target staff_directory row belongs to this user (email match)
  SELECT EXISTS (
    SELECT 1
    FROM public.staff_directory
    WHERE id = p_staff_directory_id
      AND is_active = TRUE
      AND (
        preferred_email = v_user_email
        OR work_email    = v_user_email
        OR personal_email = v_user_email
      )
  ) INTO v_matched;

  IF NOT v_matched THEN
    RAISE EXCEPTION 'You can only update your own Staff Directory photo';
  END IF;

  -- Update only the photo fields — no other fields touched
  UPDATE public.staff_directory
  SET
    photo_storage_path = p_photo_storage_path,
    photo_uploaded_at  = p_photo_uploaded_at,
    updated_at         = now()
  WHERE id = p_staff_directory_id;

  -- Return the updated row's photo fields for confirmation
  SELECT jsonb_build_object(
    'id',                 id,
    'photo_storage_path', photo_storage_path,
    'photo_uploaded_at',  photo_uploaded_at
  ) INTO v_result
  FROM public.staff_directory
  WHERE id = p_staff_directory_id;

  RETURN v_result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.user_can_access_action_item(item_office_id uuid, item_owner_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_profiles up
    WHERE up.id = auth.uid()
    AND (
      up.role::TEXT IN ('super_admin', 'admin')
      OR (up.role::TEXT = 'office_manager' AND up.office_id = item_office_id)
      OR (up.office_id = item_office_id AND up.id = item_owner_id)
    )
  )
$function$;

CREATE OR REPLACE FUNCTION public.user_can_access_huddle_office(office_uuid uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_profiles up
    WHERE up.id = auth.uid()
    AND (
      up.role::TEXT IN ('super_admin', 'admin', 'office_manager')
      OR up.office_id = office_uuid
    )
  )
$function$;

CREATE OR REPLACE FUNCTION public.user_can_access_office(target_office_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT (
    -- super_admin / admin / regional_manager / regional_clinical_manager
    user_has_all_office_access()
    -- office matches user_profiles.office_id
    OR EXISTS (
      SELECT 1 FROM public.user_profiles
      WHERE id = auth.uid() AND office_id = target_office_id
    )
    -- office is in user_office_assignments
    OR EXISTS (
      SELECT 1 FROM public.user_office_assignments
      WHERE user_id = auth.uid()
        AND (office_id = target_office_id OR all_offices = true)
    )
  );
$function$;

CREATE OR REPLACE FUNCTION public.user_can_import_to_office(p_office_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_profiles up
    WHERE up.id = auth.uid()
    AND (
      up.role = 'super_admin'
      OR up.office_id = p_office_id
      OR EXISTS (
        SELECT 1 FROM public.user_office_assignments uoa
        WHERE uoa.user_id = auth.uid()
        AND (uoa.office_id = p_office_id OR uoa.all_offices = true)
      )
    )
  );
$function$;

CREATE OR REPLACE FUNCTION public.user_can_manage_action_item(item_office_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_profiles up
    WHERE up.id = auth.uid()
    AND (
      up.role::TEXT IN ('super_admin', 'admin')
      OR (up.role::TEXT = 'office_manager' AND up.office_id = item_office_id)
    )
  )
$function$;

CREATE OR REPLACE FUNCTION public.user_has_all_office_access()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = auth.uid()
      AND role::TEXT IN (
        'super_admin',
        'admin',
        'regional_manager',
        'regional_clinical_manager'
      )
  );
$function$;

CREATE OR REPLACE FUNCTION public.user_is_admin_or_above()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.user_profiles up
    WHERE up.id = auth.uid()
    AND up.role::TEXT IN ('super_admin', 'admin', 'office_manager')
  )
$function$;

CREATE OR REPLACE FUNCTION public.validate_expense_allocation_total()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_expense_amount NUMERIC(12,2);
  v_alloc_total NUMERIC(12,2);
BEGIN
  SELECT amount INTO v_expense_amount FROM public.expenses WHERE id = NEW.expense_id;
  SELECT COALESCE(SUM(allocated_amount), 0) INTO v_alloc_total
    FROM public.expense_allocations WHERE expense_id = NEW.expense_id;
  IF v_alloc_total > v_expense_amount * 1.001 THEN
    RAISE EXCEPTION 'Allocation total (%) exceeds expense amount (%)', v_alloc_total, v_expense_amount;
  END IF;
  RETURN NEW;
END;
$function$;

