CREATE VIEW public."amex_payment_summary" AS  SELECT id,
    statement_period_start,
    statement_period_end,
    statement_month,
    statement_year,
    payment_date,
    amount_paid,
    payment_status,
    payment_reference,
    card_last4,
    card_program,
    source_type,
    notes,
    created_by,
    created_at,
    updated_at,
    'amex_payment'::text AS expense_source_type,
    date_trunc('month'::text, payment_date::timestamp with time zone) AS payment_month_start
   FROM amex_payments
  WHERE payment_status <> 'void'::amex_payment_status;

CREATE VIEW public."canonical_offices" AS  SELECT id,
    name AS raw_name,
    normalize_office_name(name) AS canonical_name,
    COALESCE(normalize_office_name(name), name) AS display_name
   FROM offices;

CREATE VIEW public."expense_facts" AS  SELECT de.id::text AS id,
    de.entry_date AS expense_date,
    COALESCE(de.expense_category, 'Uncategorized'::text) AS expense_category,
    NULL::text AS expense_subcategory,
    de.expense_amount,
    'manual'::text AS expense_source,
    de.office_id,
    o.name AS office_name,
    NULL::uuid AS gusto_employee_id,
    NULL::text AS gusto_employee_name,
    NULL::uuid AS gusto_run_id,
    NULL::date AS pay_period_start,
    NULL::date AS pay_period_end,
    'manual'::text AS source_table,
    de.id::text AS source_id,
    'resolved'::text AS office_mapping_status
   FROM daily_entries de
     LEFT JOIN offices o ON o.id = de.office_id
  WHERE de.expense_amount IS NOT NULL AND de.expense_amount > 0::numeric
UNION ALL
 SELECT gef.id,
    gef.expense_date,
    gef.expense_category,
    gef.expense_subcategory,
    gef.expense_amount,
    gef.expense_source,
    gef.office_id,
    gef.office_name,
    gef.gusto_employee_id,
    gef.gusto_employee_name,
    gef.gusto_run_id,
    gef.pay_period_start,
    gef.pay_period_end,
    gef.source_table,
    gef.source_id,
    gef.office_mapping_status
   FROM gusto_expense_facts gef;

CREATE VIEW public."sync_job_latest" AS  SELECT j.job_key,
    j.job_name,
    j.source_system,
    j.trigger_type AS job_trigger_type,
    j.schedule_description,
    j.expected_frequency_minutes,
    j.freshness_sla_minutes,
    j.is_active,
    j.is_manual_only,
    j.detail_log_table,
    j.owner,
    j.notes,
    r.id AS last_run_id,
    r.run_id AS last_run_correlation_id,
    r.status AS last_status,
    r.trigger_type AS last_trigger_type,
    r.triggered_by AS last_triggered_by,
    r.started_at AS last_started_at,
    r.completed_at AS last_completed_at,
    r.duration_ms AS last_duration_ms,
    r.rows_read AS last_rows_read,
    r.rows_inserted AS last_rows_inserted,
    r.rows_updated AS last_rows_updated,
    r.rows_failed AS last_rows_failed,
    r.error_message AS last_error,
    r.metadata AS last_metadata,
        CASE
            WHEN j.is_active = false THEN 'disabled'::text
            WHEN j.is_manual_only = true THEN 'not_applicable'::text
            WHEN j.freshness_sla_minutes IS NULL THEN 'not_applicable'::text
            WHEN r.id IS NULL THEN 'unknown'::text
            WHEN r.completed_at IS NULL AND r.status = 'running'::text THEN 'running'::text
            WHEN r.completed_at IS NULL THEN 'unknown'::text
            WHEN (EXTRACT(epoch FROM now() - r.completed_at) / 60::numeric) > j.freshness_sla_minutes::numeric THEN 'stale'::text
            WHEN (EXTRACT(epoch FROM now() - r.completed_at) / 60::numeric) > (j.freshness_sla_minutes::numeric * 0.8) THEN 'approaching'::text
            ELSE 'fresh'::text
        END AS freshness_status,
        CASE
            WHEN j.is_active = false THEN 'disabled'::text
            WHEN r.id IS NULL THEN 'not_instrumented'::text
            ELSE r.status
        END AS effective_status
   FROM sync_jobs j
     LEFT JOIN LATERAL ( SELECT sr.id,
            sr.job_key,
            sr.run_id,
            sr.trigger_type,
            sr.triggered_by,
            sr.started_at,
            sr.completed_at,
            sr.status,
            sr.rows_read,
            sr.rows_inserted,
            sr.rows_updated,
            sr.rows_failed,
            sr.duration_ms,
            sr.error_message,
            sr.error_details,
            sr.metadata,
            sr.created_at
           FROM sync_job_runs sr
          WHERE sr.job_key = j.job_key
          ORDER BY sr.started_at DESC
         LIMIT 1) r ON true;

CREATE VIEW public."v_48month_production_collections" AS  SELECT period_month,
    period_label,
    sum(gross_production) AS total_gross_production,
    sum(net_production) AS total_net_production,
    sum(abs(total_collections)) AS total_collections_abs,
    sum(total_collections) AS total_collections,
    round(sum(abs(total_collections)) / NULLIF(sum(net_production), 0::numeric) * 100::numeric, 2) AS collection_rate_pct,
    sum(ar_total) AS total_ar,
    count(DISTINCT office_canonical) AS office_count,
    count(*) FILTER (WHERE source = 'eassist_pdf_validated'::text) AS validated_offices,
    count(*) FILTER (WHERE source = 'eassist_daily_report'::text) AS imported_offices,
    count(*) FILTER (WHERE source = 'estimated_backfill'::text) AS estimated_offices
   FROM office_production_summary_monthly
  GROUP BY period_month, period_label
  ORDER BY period_month DESC;

CREATE VIEW public."v_benchmark_reconciliation_2026" AS  SELECT id,
    report_date,
    report_month,
    office_name,
    daily_production AS benchmark_daily_production,
    daily_adj AS benchmark_daily_adj,
    net_daily_production AS benchmark_net_daily_production,
    daily_insurance_coll AS benchmark_daily_insurance_coll,
    daily_patient_coll AS benchmark_daily_patient_coll,
    daily_total_coll AS benchmark_daily_total_coll,
    monthly_production AS benchmark_monthly_production,
    monthly_adj AS benchmark_monthly_adj,
    net_monthly_production AS benchmark_net_monthly_production,
    monthly_insurance_coll AS benchmark_monthly_insurance_coll,
    monthly_patient_coll AS benchmark_monthly_patient_coll,
    total_monthly_coll AS benchmark_total_monthly_coll,
    notes,
    imported_at
   FROM benchmark_eassist_daily_reports_2026 b
  ORDER BY report_date DESC, office_name;

CREATE VIEW public."v_benchmark_reconciliation_summary" AS  SELECT office_canonical,
    report_date,
    report_month,
    daily_production,
    dashboard_daily_production,
    round(daily_production - COALESCE(dashboard_daily_production, 0::numeric), 2) AS delta_daily_production,
    net_daily_production,
    dashboard_net_daily_production,
    round(net_daily_production - COALESCE(dashboard_net_daily_production, 0::numeric), 2) AS delta_net_daily_production,
    daily_total_coll,
    dashboard_daily_total_coll,
    round(daily_total_coll - COALESCE(dashboard_daily_total_coll, 0::numeric), 2) AS delta_daily_total_coll,
    monthly_production,
    dashboard_monthly_production,
    round(monthly_production - COALESCE(dashboard_monthly_production, 0::numeric), 2) AS delta_monthly_production,
    net_monthly_production,
    dashboard_net_monthly_production,
    round(net_monthly_production - COALESCE(dashboard_net_monthly_production, 0::numeric), 2) AS delta_net_monthly_production,
    total_monthly_coll,
    dashboard_total_monthly_coll,
    round(total_monthly_coll - COALESCE(dashboard_total_monthly_coll, 0::numeric), 2) AS delta_total_monthly_coll,
    mismatch_daily_production,
    mismatch_net_daily_production,
    mismatch_daily_total_coll,
    mismatch_monthly_production,
    mismatch_net_monthly_production,
    mismatch_total_monthly_coll,
        CASE
            WHEN mismatch_daily_production THEN 1
            ELSE 0
        END +
        CASE
            WHEN mismatch_net_daily_production THEN 1
            ELSE 0
        END +
        CASE
            WHEN mismatch_daily_total_coll THEN 1
            ELSE 0
        END +
        CASE
            WHEN mismatch_monthly_production THEN 1
            ELSE 0
        END +
        CASE
            WHEN mismatch_net_monthly_production THEN 1
            ELSE 0
        END +
        CASE
            WHEN mismatch_total_monthly_coll THEN 1
            ELSE 0
        END AS total_mismatches,
    reconciled_at,
    source
   FROM benchmark_eassist_daily_reports_2026
  ORDER BY report_date DESC, office_canonical;

CREATE VIEW public."v_collab_daily_ascend_finance_source" AS  WITH production AS (
         SELECT (dt.data ->> 'serviceDate'::text)::date AS activity_date,
            COALESCE(dt.location_id, (dt.data -> 'location'::text) ->> 'id'::text) AS ascend_location_id,
            round(sum((dt.data ->> 'amount'::text)::numeric), 2) AS production,
            count(*) AS completed_procedures,
            max(dt.synced_at) AS latest_sync
           FROM dentrix_transactions dt
          WHERE dt.type = 'patientprocedure'::text AND (dt.data ->> 'state'::text) = 'ACTIVE'::text AND (dt.data ->> 'status'::text) = 'COMPLETED'::text AND (dt.data ->> 'serviceDate'::text) IS NOT NULL AND (dt.data ->> 'serviceDate'::text) >= ((CURRENT_DATE - 120)::text)
          GROUP BY ((dt.data ->> 'serviceDate'::text)::date), (COALESCE(dt.location_id, (dt.data -> 'location'::text) ->> 'id'::text))
        ), collections AS (
         SELECT (dt.data ->> 'transactionDate'::text)::date AS activity_date,
            COALESCE(dt.location_id, (dt.data -> 'location'::text) ->> 'id'::text) AS ascend_location_id,
            round(abs(sum((dt.data ->> 'amount'::text)::numeric)), 2) AS collections,
            count(*) AS payment_transactions,
            max(dt.synced_at) AS latest_sync
           FROM dentrix_transactions dt
          WHERE dt.type = 'transaction'::text AND COALESCE(dt.data ->> 'isActive'::text, 'true'::text) = 'true'::text AND (dt.data ->> 'transactionDate'::text) IS NOT NULL AND (dt.data ->> 'transactionDate'::text) >= ((CURRENT_DATE - 120)::text) AND ((dt.data ->> 'ledgerType'::text) = ANY (ARRAY['PatientProcedurePayment'::text, 'PatientProcedurePaymentRebill'::text, 'InsurancePayment'::text, 'InsurancePaymentRebill'::text]))
          GROUP BY ((dt.data ->> 'transactionDate'::text)::date), (COALESCE(dt.location_id, (dt.data -> 'location'::text) ->> 'id'::text))
        ), combined AS (
         SELECT COALESCE(p.activity_date, c_1.activity_date) AS activity_date,
            COALESCE(p.ascend_location_id, c_1.ascend_location_id) AS ascend_location_id,
            COALESCE(p.production, 0::numeric) AS production,
            COALESCE(c_1.collections, 0::numeric) AS collections,
            COALESCE(p.completed_procedures, 0::bigint) AS completed_procedures,
            COALESCE(c_1.payment_transactions, 0::bigint) AS payment_transactions,
            GREATEST(p.latest_sync, c_1.latest_sync) AS latest_sync
           FROM production p
             FULL JOIN collections c_1 ON c_1.activity_date = p.activity_date AND c_1.ascend_location_id = p.ascend_location_id
        )
 SELECT c.activity_date,
    c.ascend_location_id,
    COALESCE(dl.data ->> 'name'::text, 'Unmapped Ascend location'::text) AS office_name,
    c.production,
    c.collections,
    c.completed_procedures,
    c.payment_transactions,
    c.latest_sync,
    'dentrix_transactions_live'::text AS source,
    'Production = active completed patient procedures by service date. Collections = active patient and insurance payment ledgers by transaction date.'::text AS methodology
   FROM combined c
     LEFT JOIN dentrix_locations dl ON dl.id = c.ascend_location_id;

CREATE VIEW public."v_dentrix_normalized_daily" AS  SELECT report_date,
    office_canonical AS office,
    daily_production AS gross_production_daily,
    daily_adj AS production_adjustments_daily,
    net_daily_production AS net_production_daily,
    daily_insurance_coll AS insurance_collections_daily,
    daily_patient_coll AS patient_collections_daily,
    daily_total_coll AS total_collections_daily,
    monthly_production AS gross_production_mtd,
    monthly_adj AS production_adjustments_mtd,
    net_monthly_production AS net_production_mtd,
    monthly_insurance_coll AS insurance_collections_mtd,
    monthly_patient_coll AS patient_collections_mtd,
    total_monthly_coll AS total_collections_mtd,
        CASE
            WHEN monthly_production <> 0::numeric THEN round(total_monthly_coll / NULLIF(net_monthly_production, 0::numeric) * 100::numeric, 2)
            ELSE NULL::numeric
        END AS collection_ratio_mtd,
    source,
    imported_at
   FROM benchmark_eassist_daily_reports_2026 b;

CREATE VIEW public."v_office_production_summary_reconciliation" AS  SELECT period_month,
    period_label,
    office_canonical,
    gross_production,
    net_production,
    total_collections,
    abs(total_collections) AS total_collections_abs,
    round(abs(total_collections) / NULLIF(net_production, 0::numeric) * 100::numeric, 2) AS collection_rate_pct,
    ar_total,
    source,
    reconciled_at,
    reconciliation_notes,
        CASE
            WHEN source = 'eassist_pdf_validated'::text THEN 'validated'::text
            WHEN source = 'eassist_daily_report'::text THEN 'imported'::text
            ELSE 'estimated'::text
        END AS data_quality
   FROM office_production_summary_monthly
  ORDER BY period_month DESC, office_canonical;

CREATE VIEW public."v_unscheduled_treatment_queue_with_last_contact" AS  SELECT q.id,
    q.office_id,
    q.dentrix_location_id,
    q.dentrix_patient_id,
    q.patient_name,
    q.queue_status,
    q.assigned_to,
    q.assigned_by,
    q.assigned_at,
    q.priority,
    q.follow_up_date,
    q.last_contact_at,
    q.last_contact_outcome,
    q.contact_attempt_count,
    q.last_scheduled_date,
    q.last_scheduled_appt_id,
    q.total_value,
    q.procedure_count,
    q.highest_value_procedure,
    q.primary_category,
    q.provider_name,
    q.latest_treatment_plan_date,
    q.has_future_appointment,
    q.bill_to_insurance,
    q.referred_out,
    q.source_hash,
    q.source_last_seen_at,
    q.is_current,
    q.first_synced_at,
    q.last_synced_at,
    q.created_at,
    q.updated_at,
    c.outcome AS lc_outcome,
    c.notes AS lc_notes,
    c.contacted_by_name AS lc_contacted_by_name,
    c.contact_at AS lc_contact_at,
    c.follow_up_date AS lc_follow_up_date,
    c.scheduled_date AS lc_scheduled_date
   FROM unscheduled_treatment_queue q
     LEFT JOIN LATERAL ( SELECT unscheduled_treatment_contacts.id,
            unscheduled_treatment_contacts.queue_id,
            unscheduled_treatment_contacts.office_id,
            unscheduled_treatment_contacts.dentrix_patient_id,
            unscheduled_treatment_contacts.contacted_by,
            unscheduled_treatment_contacts.contacted_by_name,
            unscheduled_treatment_contacts.contact_at,
            unscheduled_treatment_contacts.contact_date,
            unscheduled_treatment_contacts.outcome,
            unscheduled_treatment_contacts.notes,
            unscheduled_treatment_contacts.follow_up_date,
            unscheduled_treatment_contacts.scheduled_date,
            unscheduled_treatment_contacts.scheduled_appt_id,
            unscheduled_treatment_contacts.treatment_value_discussed,
            unscheduled_treatment_contacts.created_at,
            unscheduled_treatment_contacts.updated_at
           FROM unscheduled_treatment_contacts
          WHERE unscheduled_treatment_contacts.queue_id = q.id
          ORDER BY unscheduled_treatment_contacts.contact_at DESC
         LIMIT 1) c ON true;

CREATE VIEW public."v_unscheduled_treatment_staff_activity" AS  SELECT contacted_by,
    contacted_by_name,
    office_id,
    contact_date,
    count(*) AS total_contacts,
    count(*) FILTER (WHERE outcome = 'scheduled'::text) AS scheduled_count,
    count(*) FILTER (WHERE outcome = ANY (ARRAY['left_message'::text, 'no_answer'::text, 'wants_callback'::text, 'financial_concern'::text, 'insurance_issue'::text, 'not_interested'::text, 'other'::text])) AS eligible_contacted,
    count(*) FILTER (WHERE outcome = ANY (ARRAY['wrong_number'::text, 'do_not_call'::text, 'already_scheduled'::text])) AS excluded_count,
    count(*) FILTER (WHERE outcome = 'left_message'::text) AS left_message_count,
    count(*) FILTER (WHERE outcome = 'no_answer'::text) AS no_answer_count,
    count(*) FILTER (WHERE outcome = 'wants_callback'::text) AS wants_callback_count,
    count(*) FILTER (WHERE outcome = 'financial_concern'::text) AS financial_concern_count,
    count(*) FILTER (WHERE outcome = 'insurance_issue'::text) AS insurance_issue_count,
    count(*) FILTER (WHERE outcome = 'not_interested'::text) AS not_interested_count,
    count(*) FILTER (WHERE outcome = 'other'::text) AS other_count
   FROM unscheduled_treatment_contacts c
  GROUP BY contacted_by, contacted_by_name, office_id, contact_date;

CREATE MATERIALIZED VIEW public."v_collab_daily_ascend_finance" AS  SELECT activity_date,
    ascend_location_id,
    office_name,
    production,
    collections,
    completed_procedures,
    payment_transactions,
    latest_sync,
    source,
    methodology
   FROM v_collab_daily_ascend_finance_source WITH NO DATA;

